"""The SSL bus compressor, keyed (config/circuits/ssl_bus_comp.yaml, GENERATED by
scripts/make_ssl_bus_comp.py; DEVICE_BUILDER_PLAN.md B11): the generated file is current,
the pre-flight checks, the idle gain, the ratio switch's order, the keyed duck (its depth
follows the key at a constant ratio: no cliff) and its release (exponential in dB with the
RELEASE network's RC, whatever the depth), COMP OUT.

Renders run the draft with Newton at 1e-5 (the app's `panel::Device::newton` for this
device): the draft's 1e-3 is a 2 % gain error in a log-domain cell. Measured 2026-11-06
(1 kHz, ATTACK 30 ms, RELEASE 0.3 s, THRESHOLD 0.5; out vs in, 0 to +20 dBu): 2:1 -> 1.5:1,
4:1 -> 2.5:1, 10:1 -> 3.8:1; keyed at 10:1 with ATTACK 0.1 ms, 5.0 dB more duck per 6 dB
of key (6:1) at -0.8 / +5.2 / +11.2 dBu; recovery to 1/e in 81-95 ms at RELEASE 0.1 s
(180K x 0.47 uF = 85 ms)."""

import dataclasses
import subprocess
import sys

import numpy as np
import pytest

from varimu.circuit import builder
from varimu.circuit.spec import load_circuit, resolve
from varimu.config import CONFIG_DIR, REPO_ROOT

CIRCUIT = CONFIG_DIR / "circuits" / "ssl_bus_comp.yaml"
FS = 96000.0
DBU_PEAK_V = 0.775 * np.sqrt(2)
A1_DB_PER_V = 8.46  # the program VCA's control law here: 202XT's 19.6 dB/V through R13 / 4K32


def _spec():
    return load_circuit(CIRCUIT)


def _render(x: np.ndarray, key: np.ndarray | None = None, **controls):
    pytest.importorskip("circuitsim", reason="needs `uv sync --extra fast`")
    from varimu.sim import fast, io

    spec = _spec()
    q = dict(resolve(spec))
    q.update(controls)
    c = builder.build(spec, q)
    st = io.TransientSettings.from_sim_settings(engine="circuitsim", quality="draft")
    st = dataclasses.replace(st, newton_reltol=1e-5, newton_vntol=1e-5)
    key = np.zeros_like(x) if key is None else key
    return fast.run_transient(c.ir, x, controls={"key": key}, settings=st)


def _tone_out_dbu(level_dbu: float, dur_s: float = 1.2, **controls) -> float:
    n = int(FS * dur_s)
    t = np.arange(n) / FS
    x = level_dbu_v(level_dbu) * np.sin(2 * np.pi * 1000 * t) * np.clip(t / 0.01, 0, 1)
    y = np.asarray(_render(x, **controls).vectors["v(out)"])
    seg = slice(int(0.7 * n), n)
    a1 = 2 * abs(np.mean(y[seg] * np.exp(-2j * np.pi * 1000 * t[seg])))
    return 20 * np.log10(a1 / DBU_PEAK_V)


def level_dbu_v(dbu: float) -> float:
    return DBU_PEAK_V * 10 ** (dbu / 20)


def test_generated_file_is_current():
    r = subprocess.run(
        [sys.executable, str(REPO_ROOT / "scripts" / "make_ssl_bus_comp.py"), "--check"],
        capture_output=True,
        text=True,
    )
    assert r.returncode == 0, r.stdout + r.stderr


def test_passes_the_preflight_checks_at_the_panel_defaults():
    from varimu import preflight

    ir = builder.build_ir(_spec(), resolve(_spec()))
    assert preflight.check_ir(ir) == []


def test_below_threshold_it_passes_the_program():
    """-15 dBu, no gain reduction: the 202XT's 1.25 kOhm in series with R12 is the only loss
    (20 log(15 / 16.25) = -0.70 dB)."""
    out = _tone_out_dbu(-15.0, dur_s=0.4, ratio=4, attack=5, release=1)
    assert out == pytest.approx(-15.70, abs=0.1)


def test_ratio_switch_order():
    """The steady slope above threshold rises 2 < 4 < 10 (the contacts' order is derived,
    the drawing doesn't name them; the values are softer than the panel's: the module
    docstring)."""
    slopes = {}
    for ratio in (2, 4, 10):
        lo = _tone_out_dbu(5.0, ratio=ratio, attack=5, release=1)
        hi = _tone_out_dbu(20.0, ratio=ratio, attack=5, release=1)
        slopes[ratio] = 15.0 / (hi - lo)
    assert 1.2 < slopes[2] < slopes[4] < slopes[10], slopes


def _kick(amp_v: float, n: int, t0_s: float = 0.5) -> np.ndarray:
    t = np.arange(n) / FS
    k = np.zeros(n)
    m = (t >= t0_s) & (t < t0_s + 0.3)
    tt = t[m] - t0_s
    k[m] = amp_v * np.sin(2 * np.pi * 55 * tt) * np.exp(-tt / 0.08)
    return k


def test_keyed_duck_holds_its_ratio_and_releases_with_its_rc():
    """A kick-like key (55 Hz, 80 ms decay) ducks a held 110 Hz sawtooth at KEY EXT: each 6
    dB more key ducks the same few dB more (a ratio, not the keyed 670's cliff), and the
    duck recovers to 1/e within 25 % of RELEASE 0.1 s's 180K x 0.47 uF at every depth."""
    n = int(FS * 1.0)
    t = np.arange(n) / FS
    saw = 2 * ((110 * t) % 1.0) - 1
    depths, taus = [], []
    for amp in (1.0, 2.0, 4.0):
        r = _render(saw, _kick(amp, n), key_mode=1, ratio=10, attack=0, release=0)
        gr = np.asarray(r.vectors["v(vb)"])[::96] * A1_DB_PER_V  # dB, 1 ms steps
        seg = gr[500:]
        k = int(np.argmax(seg))
        depths.append(seg[k])
        taus.append(int(np.argmax(seg[k:] < seg[k] / np.e)) * 1e-3)
    steps = np.diff(depths)
    assert depths[0] > 1.0 and np.all(steps > 2.0), depths
    assert abs(steps[1] - steps[0]) < 0.5, depths  # the same ratio at every level
    for tau in taus:
        assert tau == pytest.approx(180e3 * 0.47e-6, rel=0.25), taus


def test_comp_out_doesnt_compress():
    out = _tone_out_dbu(15.0, dur_s=0.5, comp_in=0, ratio=10, attack=0, release=0)
    assert out == pytest.approx(15.0 - 0.70, abs=0.15)
